# 方法一：回溯（推薦）
class Solution:
    def letterCombinations(self, digits: str) -> List[str]:
        if not digits:
            return []                 # 注意：空輸入回傳 []，不是 [""]

        phone = {
            '2': 'abc', '3': 'def', '4': 'ghi', '5': 'jkl',
            '6': 'mno', '7': 'pqrs', '8': 'tuv', '9': 'wxyz'
        }

        result = []
        path = []

        def backtrack(index):
            # 所有數字都處理完了
            if index == len(digits):
                result.append(''.join(path))
                return

            for ch in phone[digits[index]]:
                path.append(ch)          # ① 做選擇
                backtrack(index + 1)     # ② 下一位數字
                path.pop()               # ③ 撤銷選擇

        backtrack(0)
        return result


# 方法二：BFS 迭代
class Solution:
    def letterCombinations(self, digits: str) -> List[str]:
        if not digits:
            return []

        phone = {
            '2': 'abc', '3': 'def', '4': 'ghi', '5': 'jkl',
            '6': 'mno', '7': 'pqrs', '8': 'tuv', '9': 'wxyz'
        }

        result = ['']
        for d in digits:
            # 每一輪把現有結果與新字母做笛卡爾積
            result = [prefix + ch for prefix in result for ch in phone[d]]
        return result

